let stopAdhkarLanguage=()=>{};
function paint(html,afterTranslate=()=>{}){stopAdhkarLanguage();host.innerHTML=uiHtml(html);stopAdhkarLanguage=watchPracticeUi(host,afterTranslate);}
function adhkarMessage(value){const key=Object.hasOwn(ADHKAR_TEXT_KEYS,value)?ADHKAR_TEXT_KEYS[value]:null;return key?uiMessage(key,value):value;}
function toastUi(value){toast(adhkarMessage(value));}

const progressStore=createAdhkarProgressStore({storage:()=>localStorage,day:()=>dateKey(),locks:()=>navigator.locks});
const freeStore=createFreeCounterStore({storage:()=>localStorage,locks:()=>navigator.locks,changed:()=>window.dispatchEvent(new Event('salah:counter-changed'))});
const feedback=createDhikrFeedback({read,write,haptic:()=>settings.haptic,environment:()=>window,onError:()=>toastUi('Настройка не сохранилась. Повторите.')});
const formatTotal=n=>uiNumber(n);
const readingSizes=[16,18,20,22,24,28];
function readingSize(){const value=read('adhkar-font-size',18);return readingSizes.includes(value)?value:18}
let disposeSwipe=null,counterTimer=0;
const clearCounter=()=>{window.clearTimeout(counterTimer);counterTimer=0;};
function clearSwipe(){disposeSwipe?.();disposeSwipe=null}
let activePeriod=null,data=null,host=null,group=null,cursor=0,token=0,suppressTapUntil=0,dhikrAudio=null,dhikrAudioToken=0,renderedRoute=null,eveningDay=null,resumePreviousEvening=null;
const names={morning:'Утренние азкары',evening:'Вечерние азкары'};
function progress(g){
 const current=progressStore.progress(g);
 if(g!=='evening')return current;
 if(g===group&&eveningDay)return progressStore.progress(g,eveningDay);
 const previous=resumePreviousEvening===true&&!Object.values(current.counts).some(n=>n>0)?progressStore.previous(g):null;
 const result=previous||current;
 if(g===group&&(resumePreviousEvening!==null||Object.values(current.counts).some(n=>n>0)))eveningDay=result._day;
 return result;
}
function save(p){const ok=progressStore.save(group,{...p,_day:p._day||progress(group)._day});if(!ok)toastUi('Прогресс не сохранился. Проверьте доступ к хранилищу.');return ok}
function countFor(p,item){return Math.min(item.target,Math.max(0,Number(p.counts[item.id])||0))}
function completed(p,g){return data.groups[g].ids.filter(id=>countFor(p,data.items.find(i=>i.id===id))>=data.items.find(i=>i.id===id).target).length}
const adhkarParentKey='salahAdhkarParent';
// Keep the collection menu in real history so native iPhone Back uses it too.
// Card paging replaces only the child entry; it never accumulates card history.
function enterAdhkarView(hash){
 if(location.hash===hash)return;
 if(location.hash==='#adhkar'&&hash.startsWith('#adhkar?')){
  location.hash=hash;
  window.history.replaceState({...window.history.state,[adhkarParentKey]:true},'',hash);
 }else window.history.replaceState(window.history.state,'',hash);
}
function ensureAdhkarMenuHistory(){
 if(!location.hash.startsWith('#adhkar?')||window.history.state?.[adhkarParentKey])return;
 const hash=location.hash,state={...window.history.state},child={...state,[adhkarParentKey]:true};
 delete child.salahRouteStep;
 window.history.replaceState(state,'','#adhkar');
 window.history.pushState(child,'',hash);
 window.dispatchEvent(new Event('salah:route-history'));
}
function rememberView(view='hub',item=null){
 const params=new URLSearchParams();if(group)params.set('group',group);if(view!=='hub'&&view!=='list')params.set('view',view);if(item)params.set('item',item);if(group==='evening'){const p=progress(group);if(p._day!==dateKey())params.set('day',p._day)}
 const hash='#adhkar'+(params.size?'?'+params.toString():'');
 try{if(hash==='#adhkar'&&location.hash!==hash&&window.history.state?.[adhkarParentKey])window.history.back();else enterAdhkarView(hash)}catch{try{window.history.replaceState(window.history.state,'',hash)}catch{}}
 renderedRoute=hash;
}
function restoreGroup(requested){if(requested==='morning'||requested==='evening')return requested;if(requested==='all'){data.groups.all={name:'Все зикры',ids:data.items.map(item=>item.id)};return requested}if(requested==='favorites'){const favorites=read('adhkar-favorites',[]);data.groups.favorites={name:'Избранное',ids:(Array.isArray(favorites)?favorites:[]).filter(id=>data.items.some(item=>item.id===id))};return requested}return null}
export function stopAdhkar(){stopAdhkarLanguage();stopAdhkarLanguage=()=>{};feedback.stop();clearCounter();clearSwipe();renderedRoute=null;eveningDay=null;token++;stopDailyDuas();stopDhikrAudio();document.body.classList.remove('adhkar-focus','adhkar-signature','adhkar-hybrid','adhkar-reading','adhkar-hub-open');if(document.getElementById('short-dhikr-picker'))closeModal()}
export function adhkarHomeCard(period){if(!names[period])return '';const key=period==='morning'?'home.morningAdhkar':period==='evening'?'home.eveningAdhkar':null;return '<a class="home-adhkar-prompt" href="#adhkar?group='+period+'" data-adhkar-open="'+period+'">'+icon(period==='morning'?'sun':'moon-stars')+'<span'+(key?' data-i18n="'+key+'"':'')+'>'+esc(key?t(key):names[period])+'</span></a>'}
export function selectAdhkar(g){write('adhkar-selected',g)}
export async function showAdhkar(container,period=null,{resumeEvening=null}={}){
 activePeriod=period;resumePreviousEvening=resumeEvening;
 // Returning from another app refreshes prayer data, not the reading screen.
 if(data&&host===container&&renderedRoute===location.hash&&host.querySelector('.adhkar-shell,.dhikr-list-shell,.hybrid-heading,.lesson-complete,.daily-dua-shell')){updateAdhkarPeriod(period,{resumeEvening});return}
 stopDailyDuas();host=container;const version=++token;paint("<section class=\"panel section\"><h1 data-i18n=\"nav.adhkar\">Азкары</h1><p class=\"muted\" data-i18n=\"adhkarUi.loadingMaterials\">Открываем материалы…</p></section>");
 try{if(!data){const r=await fetch('./data/adhkar.json');if(!r.ok)throw Error();const d=await r.json();if(version!==token)return;data=d}if(version!==token)return;
  if(!progressStore.configure(data.items))toastUi('Прогресс не сохранился. Проверьте доступ к хранилищу.');
  const params=new URLSearchParams(location.hash.split('?')[1]||'');group=restoreGroup(params.get('group'));eveningDay=null;if(group==='evening'){const requested=params.get('day'),today=dateKey(),previous=progressStore.previous(group);if((requested===today||requested===previous?._day)&&progressStore.hasDay(group,requested))eveningDay=requested}if(group||['duas','counter'].includes(params.get('view')))ensureAdhkarMenuHistory();
  if(params.get('view')==='duas'){if(document.getElementById('short-dhikr-picker'))closeModal();document.body.classList.remove('adhkar-hub-open');group=null;stopDhikrAudio();await showDailyDuas(host,{onBack:()=>{stopDailyDuas();hub()},onRoute:()=>{renderedRoute=location.hash}});return}
  else if(params.get('view')==='counter'){group=null;freeCounter()}
  else if(group){const index=data.groups[group].ids.indexOf(params.get('item'));if(params.get('view')==='card'&&index>=0){cursor=index;card()}else if(params.get('view')==='summary')summary();else list()}
  else hub();
 }catch{if(version!==token)return;renderedRoute=null;paint("<section class=\"panel section\"><h1 data-i18n=\"adhkarUi.materialsUnavailable\">Материалы недоступны</h1><button class=\"button\" id=\"adhkar-retry\" data-i18n=\"common.retry\">Повторить</button></section>");host.querySelector('#adhkar-retry').onclick=()=>showAdhkar(host,activePeriod,{resumeEvening:resumePreviousEvening})}
}
// The adhkar cards show the surah verses without the opening basmala.
// Keep the source catalogue and the Quran reader unchanged.
function displayedVerses(item){
 const verses=item.verses||[item];
 if(!['surah112','surah113','surah114'].includes(item.id))return verses;
 return verses.map((verse,index)=>index?verse:{...verse,
  arabic:verse.arabic.replace(/^بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\s+/u,''),
  transliteration:verse.transliteration.replace(/^Бисмилляахир-рахмаанир-рахиим\.\s+/u,'')
 });
}
function readingText(item){const shown=adhkarPresentation(item),text=displayedVerses(shown),verses=item.verses?[{arabic:text.map(v=>v.arabic).join(' '),transliteration:text.map(v=>v.transliteration).join(' '),translation:text.map(v=>v.translation).join(' ')}]:text,recording=adhkarRecording(item);return uiHtml('<section class="lesson-passage dhikr-passage"'+(['surah112','surah113','surah114'].includes(item.id)?' data-mushaf-surah="true"':'')+'><h2 class="dhikr-reading-title" lang="ru" translate="no">'+esc(shown.title)+'</h2><div class="passage-body">'+verses.map(v=>'<div class="lesson-verse"><p class="arabic dhikr-arabic" dir="rtl" lang="ar" translate="no" '+(!read('adhkar-arabic',false)?'hidden':'')+'>'+esc(v.arabic)+'</p><div class="transliteration" lang="ru" translate="no" '+(!read('adhkar-translit',true)?'hidden':'')+'><p>'+esc(v.transliteration)+'</p></div><p class="translation-label" '+(!read('adhkar-translation',true)?'hidden':'')+"><span data-i18n=\"adhkarUi.translation\">Перевод</span></p><p class=\"lesson-translation\" lang=\"ru\" translate=\"no\" "+(!read('adhkar-translation',true)?'hidden':'')+'>'+esc(v.translation)+'</p></div>').join('')+"<div class=\"dhikr-footer\"><p class=\"lesson-author\"><button class=\"dhikr-explanation\" type=\"button\" data-i18n=\"adhkarUi.explanation\">Пояснение смысла</button></p>"+(recording?"<div class=\"dhikr-audio-inline\"><button class=\"dhikr-audio-toggle\" id=\"dhikr-play\" type=\"button\" aria-label=\"Прослушать азкар\" data-i18n-aria-label=\"adhkarUi.audioPlay\" title=\"Прослушать азкар\" data-i18n-title=\"adhkarUi.audioPlay\"><svg class=\"dhikr-audio-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 6 18 12 9 18Z\"/></svg></button><span class=\"dhikr-audio-message\" id=\"dhikr-audio-status\" role=\"status\" aria-live=\"polite\"></span></div>":"<p class=\"muted dhikr-audio-pending\" data-i18n=\"adhkarUi.audioPending\">Аудио с этой формулировкой пока подбираем.</p>")+'</div></div></section>')}

function card(direction=0,incoming=null){feedback.stop();if(document.getElementById('short-dhikr-picker'))closeModal();clearCounter();incoming?.remove();markDhikrActivity();clearSwipe();stopDhikrAudio();theme();document.body.classList.add('adhkar-reading');const g=data.groups[group],p=progress(group),item=data.items.find(i=>i.id===g.ids[cursor]),n=countFor(p,item),done=completed(p,group),size=readingSize();rememberView('card',item.id);document.body.classList.toggle('adhkar-focus',read('adhkar-focus',true));p.cursor=cursor;save(p);paint('<div class="lesson-shell adhkar-shell" style="--reading-size:'+size+'px;--arabic-size:'+size*1.8+"px\"><div class=\"adhkar-reading-content\" role=\"region\" aria-label=\"Текст азкара\" data-i18n-aria-label=\"adhkarUi.textRegion\" tabindex=\"0\"><div class=\"lesson-top\"><button class=\"text-button\" id=\"adhkar-close\" data-i18n=\"adhkarUi.back\">К азкарам</button><span>"+adhkarGroupLeaf(group,g.name)+'</span><span id="adhkar-completed-count">'+uiLeaf('adhkarUi.completedCount',ADHKAR_UI_SOURCE.completedCount,{done,total:g.ids.length})+'</span></div><div class="progress"><span style="width:'+done/g.ids.length*100+"%\"></span></div><details class=\"adhkar-settings\"><summary data-i18n=\"adhkarUi.readingSettings\">Настройки чтения</summary><div class=\"adhkar-preferences\"><label><span data-i18n=\"adhkarUi.textSize\">Размер текста</span> <select id=\"adhkar-size\">"+readingSizes.map(n=>'<option '+(size===n?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label><input type="checkbox" id="adhkar-focus" '+(read('adhkar-focus',true)?'checked':'')+"> <span data-i18n=\"adhkarUi.readingMode\">Режим чтения</span></label><label><input type=\"checkbox\" id=\"adhkar-arabic\" "+(read('adhkar-arabic',false)?'checked':'')+"> <span data-i18n=\"adhkarUi.arabic\">Арабский</span></label><label><input type=\"checkbox\" id=\"adhkar-translation\" "+(read('adhkar-translation',true)?'checked':'')+"> <span data-i18n=\"adhkarUi.translation\">Перевод</span></label><label><input type=\"checkbox\" id=\"adhkar-translit\" "+(read('adhkar-translit',true)?'checked':'')+"> <span data-i18n=\"adhkarUi.transliteration\">Транслитерация</span></label>" +feedback.markup()+'<p class="muted adhkar-transcription-guide" lang="ru" translate="no">Транскрипция — подсказка к чтению. Аа, ии, уу обозначают долгие гласные. Точка — остановка чтения. Для точного произношения слушайте запись.</p></div></details><span class="eyebrow">'+uiLeaf('adhkarUi.cardPosition',ADHKAR_UI_SOURCE.cardPosition,{index:cursor+1,total:g.ids.length})+'</span>'+readingText(item)+'</div><div class="dhikr-counter-dock"><button id="adhkar-count" data-dhikr-id="'+item.id+'" class="dhikr-counter" style="--count-progress:'+n/item.target*100+'%" '+(n>=item.target?'disabled':'')+' aria-label="'+(n>=item.target?'Выполнено':'Отметить повторение')+'"><span class="count-number">'+n+'<small> / '+item.target+'</small></span><span class="count-caption">'+(n>=item.target?'✓ Выполнено':'')+"</span></button><p id=\"adhkar-continue-hint\" class=\"dhikr-continue-hint\" role=\"status\" hidden></p><p class=\"dhikr-lifetime\"><span data-i18n=\"adhkarUi.total\">Всего</span><strong id=\"adhkar-total\" aria-live=\"polite\">"+formatTotal(progressStore.total(item.id))+'</strong></p></div><div class="button-row adhkar-counter-tools" hidden><button class="text-button" id="adhkar-undo" '+(!n?'disabled':'')+"><span data-i18n=\"adhkarUi.undoOneRepetition\">− Одно повторение</span></button><button class=\"text-button\" id=\"adhkar-reset\" data-i18n=\"adhkarUi.resetCard\">Сбросить карточку</button></div><div class=\"adhkar-navigation\" hidden><button class=\"button secondary\" id=\"adhkar-prev\" "+(!cursor?'disabled':'')+"><span data-i18n=\"adhkarUi.previous\">Предыдущий</span></button><button class=\"button\" id=\"adhkar-next\">"+uiLeaf(cursor===g.ids.length-1?'adhkarUi.toSummary':'adhkarUi.nextDhikr',cursor===g.ids.length-1?'К итогам':'Следующий зикр')+'</button></div></div>');host.querySelector('.adhkar-shell').dataset.slide=direction>0?'next':direction<0?'previous':'';if(incoming)host.querySelector('.dhikr-passage').replaceWith(incoming);bindDhikrAudio(item);feedback.bind(host);readingLayout();host.querySelector('#adhkar-close').onclick=()=>{stopAdhkar();hub()};host.querySelector('#adhkar-size').onchange=e=>{const n=Number(e.target.value);if(!readingSizes.includes(n))return;write('adhkar-font-size',n);const shell=host.querySelector('.lesson-shell');shell.style.setProperty('--reading-size',n+'px');shell.style.setProperty('--arabic-size',n*1.8+'px');readingLayout()};host.querySelector('#adhkar-focus').onchange=e=>{write('adhkar-focus',e.target.checked);document.body.classList.toggle('adhkar-focus',e.target.checked)};host.querySelector('#adhkar-arabic').onchange=e=>{write('adhkar-arabic',e.target.checked);host.querySelectorAll('.dhikr-arabic').forEach(x=>x.hidden=!e.target.checked);readingLayout()};host.querySelector('#adhkar-translation').onchange=e=>{write('adhkar-translation',e.target.checked);host.querySelectorAll('.lesson-translation,.translation-label').forEach(x=>x.hidden=!e.target.checked);readingLayout()};host.querySelector('.dhikr-explanation').onclick=()=>hadithInfo(item);host.querySelector('.passage-body').onclick=e=>{if(Date.now()>suppressTapUntil&&!e.target.closest('summary,a,button,input,select,textarea,.dhikr-audio-player'))hadithInfo(item)};host.querySelector('#adhkar-translit').onchange=e=>{write('adhkar-translit',e.target.checked);host.querySelectorAll('.transliteration').forEach(d=>d.hidden=!e.target.checked);readingLayout()};host.querySelector('#adhkar-count').onclick=async e=>{const activityAccount=localStorage.getItem('salah:counter-active-account'),activityGroup=group;const button=e.currentTarget;if(button.dataset.pending||button!==host.querySelector('#adhkar-count'))return;const current=progress(group),action=button.dhikrGate.action({day:current._day,count:countFor(current,item),target:item.target});if(action==='wait')return;if(action==='unlock'){updateCount(item,current);return;}const tapFeedback=feedback.prepare();button.dataset.pending='true';button.disabled=true;const result=await (action==='extra'?progressStore.incrementExtra(group,item.id,current._day):progressStore.increment(group,item.id,current._day));delete button.dataset.pending;if(!result.ok){toastUi('Повторение не сохранилось. Проверьте доступ к хранилищу.');if(button===host.querySelector('#adhkar-count'))updateCount(item,progress(group));return}if(result.changed){markDhikrActivity();emitAdhkarActivity(activityAccount);emitTransientDhikrPresence(activityAccount);recordAdhkarRound(activityAccount,activityGroup,result.progress);}if(result.changed&&button===host.querySelector('#adhkar-count')&&activityAccount===localStorage.getItem('salah:counter-active-account'))tapFeedback(action==='prescribed'&&countFor(result.progress,item)===item.target);if(button===host.querySelector('#adhkar-count'))updateCount(item,result.progress,result.total)};host.querySelector('#adhkar-undo').onclick=async()=>{const result=await progressStore.undo(group,item.id,progress(group)._day);if(!result.ok){toastUi('Изменение не сохранилось. Проверьте доступ к хранилищу.');return}if(host.querySelector('#adhkar-count')?.dataset.dhikrId===item.id)updateCount(item,result.progress,result.total)};host.querySelector('#adhkar-reset').onclick=()=>resetConfirm(()=>{const current=progress(group);current.counts[item.id]=0;if(current.extraCounts)delete current.extraCounts[item.id];if(save(current))updateCount(item,current)});updateCount(item,p);host.querySelector('#adhkar-prev').onclick=()=>{cursor--;card(-1);window.scrollTo(0,0)};bindSwipe();host.querySelector('#adhkar-next').onclick=()=>{if(cursor<g.ids.length-1){cursor++;card(1)}else summary();window.scrollTo(0,0)}}
function updateCount(item,p,total=progressStore.total(item.id)){
 const n=countFor(p,item),done=completed(p,group),button=host?.querySelector('#adhkar-count');if(!button||button.dataset.dhikrId!==item.id)return;
 const gate=button.dhikrGate||(button.dhikrGate=createDhikrCompletionGate()),state=gate.sync({day:p._day,count:n,target:item.target}),extras=p.extraCounts?.[item.id]||0;
 button.disabled=Boolean(state.remaining||button.dataset.pending);button.setAttribute('aria-disabled',String(button.disabled));button.style.setProperty('--count-progress',n/item.target*100+'%');button.dataset.extra=String(state.extra);
 const label=state.extra?'Отметить дополнительное повторение':state.complete?(state.remaining?'Выполнил':'Продолжить дополнительный зикр'):'Отметить повторение';uiAttribute(button,'aria-label',ADHKAR_TEXT_KEYS[label],label);
 button.querySelector('.count-number').innerHTML=state.extra?uiNumberLeaf(extras)+'<small>'+uiLeaf('adhkarUi.extraSuffix',' дополнительно')+'</small>':uiNumberLeaf(n)+'<small> / '+uiNumberLeaf(item.target)+'</small>';
 uiSource(button.querySelector('.count-caption'),state.extra?'Зикр в своём темпе':state.complete?'✓ Выполнил':'',ADHKAR_TEXT_KEYS);
 const hint=host.querySelector('#adhkar-continue-hint');if(hint){hint.hidden=!state.complete||state.remaining>0;uiSource(hint,state.extra?'Основное количество выполнено. Дополнительные повторения считаются отдельно.':'Нажмите ещё раз, чтобы продолжить зикр.',ADHKAR_TEXT_KEYS);}
 clearCounter();if(state.remaining)counterTimer=window.setTimeout(()=>{if(button===host?.querySelector('#adhkar-count'))updateCount(item,progress(group));},state.remaining+10);
 uiNumberSet(host.querySelector('#adhkar-total'),total);host.querySelector('#adhkar-undo').disabled=!n&&!extras;uiSet(host.querySelector('#adhkar-completed-count'),'adhkarUi.completedCount',ADHKAR_UI_SOURCE.completedCount,{done,total:data.groups[group].ids.length});host.querySelector('.progress span').style.width=done/data.groups[group].ids.length*100+'%';
}
function summary(){feedback.stop();clearCounter();clearSwipe();rememberView('summary');stopDhikrAudio();document.body.classList.remove('adhkar-reading','adhkar-focus');const g=data.groups[group],p=progress(group),done=completed(p,group),finished=done===g.ids.length;
 paint('<section class="panel section lesson-complete"><span class="eyebrow">'+adhkarGroupLeaf(group,g.name)+'</span><h1 id="adhkar-summary-title"></h1><p class="muted">'+uiLeaf(finished?'adhkarUi.finishSet':'adhkarUi.returnRemaining',finished?ADHKAR_UI_SOURCE.finishSet:ADHKAR_UI_SOURCE.returnRemaining)+'</p><div class="button-row"><button id="adhkar-return" class="button">'+uiLeaf(finished?'adhkarUi.openSet':'adhkarUi.continue',finished?ADHKAR_UI_SOURCE.openSet:ADHKAR_UI_SOURCE.continue)+'</button><button id="adhkar-hub" class="button secondary" data-i18n="adhkarUi.allAdhkar">Все азкары</button><button id="adhkar-new" class="text-button" data-i18n="adhkarUi.startSetAgain">Начать набор заново</button></div></section>',()=>{
  uiSet(host.querySelector('#adhkar-summary-title'),finished?'adhkarUi.groupCompleted':'adhkarUi.savedCount',finished?ADHKAR_UI_SOURCE.groupCompleted:ADHKAR_UI_SOURCE.savedCount,{group:adhkarGroupLabel(group,g.name),done,total:g.ids.length});
 });
 host.querySelector('#adhkar-return').onclick=()=>{cursor=Math.max(0,g.ids.findIndex(id=>countFor(p,data.items.find(i=>i.id===id))<data.items.find(i=>i.id===id).target));card()};host.querySelector('#adhkar-hub').onclick=hub;host.querySelector('#adhkar-new').onclick=()=>resetConfirm(()=>{if(save({cursor:0,counts:{}})){cursor=0;card()}})
}
function resetConfirm(action){uiModal("<h2 data-i18n=\"adhkarUi.resetQuestion\">Сбросить счётчик?</h2><p class=\"muted\" data-i18n=\"adhkarUi.resetNote\">Счётчик будет сброшен.</p><div class=\"button-row\"><button class=\"button\" id=\"confirm-dhikr-reset\" data-i18n=\"adhkarUi.reset\">Сбросить</button><button class=\"button secondary\" data-close data-i18n=\"common.cancel\">Отмена</button></div>");document.querySelector('#confirm-dhikr-reset').onclick=()=>{closeModal();action()}}
function freeCounter(){feedback.stop();
 clearCounter();markDhikrActivity();clearSwipe();group=null;rememberView('counter');stopDhikrAudio();
 document.body.classList.remove('adhkar-reading','adhkar-hub-open');document.body.classList.add('adhkar-focus');
 const p=freeStore.snapshot();if(!p.ok){toastUi('Не удалось открыть сохранённый счётчик. Проверьте доступ к хранилищу.');hub();return;}
 const chosen=shortDhikr(p),arabicText=chosen.arabic||(/[\u0600-\u06ff]/u.test(chosen.text||'')?chosen.text:null);
 paint("<section class=\"lesson-shell adhkar-shell short-counter-page\"><div class=\"lesson-top\"><button class=\"text-button\" id=\"counter-close\" data-i18n=\"adhkarUi.backArrow\">← К азкарам</button><span data-i18n=\"adhkarUi.customCounterEyebrow\">СВОЙ СЧЁТЧИК</span></div><button class=\"short-counter-choice\" id=\"short-dhikr-choose\" type=\"button\"><span><small data-i18n=\"adhkarUi.chooseDhikrEyebrow\">ВЫБРАТЬ ЗИКР</small><strong translate=\"no\" dir=\"auto\" lang=\""+(chosen.text?'':'ru')+'">'+esc(chosen.title)+'</strong></span><span aria-hidden="true">⌄</span></button><div class="short-counter-passage"><p class="'+(arabicText?'arabic':'short-counter-own-text')+'" lang="'+(arabicText?'ar':'')+'" dir="'+(arabicText?'rtl':'auto')+'">'+esc(arabicText||chosen.text)+'</p>'+(chosen.meaning?'<p class="short-counter-meaning" lang="ru" translate="no">'+esc(chosen.meaning)+'</p>':'')+"</div><div class=\"short-counter-goal\"><label for=\"counter-target\" data-i18n=\"adhkarUi.goal\">Цель</label><select id=\"counter-target\"><option value=\"33\" data-i18n=\"adhkarUi.repeat33\">33 повторения</option><option value=\"100\" data-i18n=\"adhkarUi.repeat100\">100 повторений</option><option value=\"0\" data-i18n=\"adhkarUi.noGoal\">Без цели</option><option value=\"custom\" data-i18n=\"adhkarUi.customGoal\">Своя цель</option></select><input id=\"counter-custom\" type=\"number\" min=\"1\" max=\"100000\" step=\"1\" aria-label=\"Своя цель\" data-i18n-aria-label=\"adhkarUi.customGoal\" hidden></div><button class=\"dhikr-counter\" id=\"free-tap\"><span class=\"count-number\" aria-live=\"polite\">"+p.count+'</span><span class="count-caption">'+(p.target?'Цель: '+p.target:'Без цели')+'</span></button>' +feedback.markup()+"<div class=\"short-counter-tools\"><button class=\"text-button\" id=\"free-minus\" type=\"button\" data-i18n=\"adhkarUi.undoOne\">− Одно</button><button class=\"text-button\" id=\"free-reset\" type=\"button\" data-i18n=\"adhkarUi.newRound\">Новый круг</button></div><p class=\"dhikr-lifetime\"><span data-i18n=\"adhkarUi.customLifetime\">Всего в своём счётчике</span><strong id=\"free-total\" aria-live=\"polite\">"+formatTotal(p.total)+"</strong></p><p class=\"short-counter-note\" data-i18n=\"adhkarUi.counterNote\">Счёт каждого зикра сохраняется отдельно. Цель выбираете вы.</p></section>");
 feedback.bind(host);const select=host.querySelector('#counter-target'),custom=host.querySelector('#counter-custom');select.value=[0,33,100].includes(p.target)?String(p.target):'custom';custom.hidden=select.value!=='custom';custom.value=p.target||33;
 const account=p.account,screen=host.querySelector('#free-tap');const current=()=>host?.querySelector('#free-tap')===screen;
 const store=async(action,value)=>{const tapFeedback=action==='increment'?feedback.prepare():null;const result=await freeStore.change(action,value,account);if(result.ok&&action==='increment'){markDhikrActivity();emitAdhkarActivity(account);emitTransientDhikrPresence(account);}if(!current())return;if(!result.ok){toastUi(result.reason==='account_changed'?'Аккаунт изменился. Откройте счётчик снова.':'Счёт не сохранился. Проверьте доступ к хранилищу.');updateFreeCount();return;}updateFreeCount();if(action==='increment')tapFeedback?.();};
 select.onchange=()=>{custom.hidden=select.value!=='custom';if(select.value==='custom'&&!custom.checkValidity())return;return store('target',select.value==='custom'?Number(custom.value):Number(select.value));};
 custom.onchange=()=>{if(!custom.checkValidity()){custom.reportValidity();return;}return store('target',Number(custom.value));};
 host.querySelector('#free-tap').onclick=()=>store('increment');host.querySelector('#free-minus').onclick=()=>store('undo');host.querySelector('#free-reset').onclick=()=>resetConfirm(()=>store('reset'));host.querySelector('#counter-close').onclick=hub;host.querySelector('#short-dhikr-choose').onclick=shortCounterPicker;
 screen.dataset.account=account;screen.dataset.dhikr=p.selected||DEFAULT_SHORT_DHIKR;updateFreeCount();
}
function shortCounterPicker(){
 const p=freeStore.snapshot(),screen=host?.querySelector('#free-tap');if(!p.ok||!screen)return;
 const active=()=>host?.querySelector('#free-tap')===screen&&screen.dataset.account===p.account;
 const rows=[...SHORT_DHIKR_PRESETS,...(p.custom||[])];
 uiModal("<section id=\"short-dhikr-picker\"><div class=\"modal-head\"><h2 data-i18n=\"adhkarUi.chooseDhikr\">Выберите зикр</h2><button class=\"text-button\" data-close type=\"button\" data-i18n=\"common.close\">Закрыть</button></div><p class=\"short-picker-note\" data-i18n=\"adhkarUi.pickerNote\">Можно продолжить любой зикр с сохранённого места.</p><div class=\"short-dhikr-list\">"+rows.map(item=>{const selected=item.id===(p.selected||DEFAULT_SHORT_DHIKR),count=selected?p.count:p.rounds?.[item.id]?.count||0;return'<div class="short-dhikr-row"><button class="short-dhikr-option" type="button" data-short-dhikr="'+item.id+'" aria-pressed="'+selected+'"><span class="short-dhikr-copy"><strong translate="no" dir="auto" lang="'+(item.text?'':'ru')+'">'+esc(item.title)+'</strong><span translate="no" dir="'+(item.arabic?'rtl':'auto')+'"'+(item.arabic?' lang="ar" class="short-dhikr-ar"':' lang=""')+'>'+esc(item.arabic||item.text)+'</span></span><span class="short-dhikr-count">'+(count?uiNumberLeaf(count):selected?'✓':'→')+'</span></button>'+(item.text?'<button class="short-dhikr-remove" type="button" data-remove-short="'+item.id+'"'+uiAttributeAttrs('aria-label','adhkarUi.removeNamed',{name:item.title})+'>×</button>':'')+'</div>';}).join('')+"</div><button class=\"button secondary short-custom-open\" id=\"short-custom-open\" type=\"button\" aria-expanded=\"false\" data-i18n=\"adhkarUi.addCustom\">+ Добавить свой зикр</button><form id=\"short-custom-form\" hidden><label><span data-i18n=\"adhkarUi.titleLabel\">Название</span><input name=\"title\" required maxlength=\"60\" placeholder=\"Как назвать зикр\" data-i18n-placeholder=\"adhkarUi.namePlaceholder\"></label><label><span data-i18n=\"adhkarUi.textLabel\">Текст зикра</span><textarea name=\"text\" required maxlength=\"240\" rows=\"3\" dir=\"auto\" placeholder=\"На арабском или в транскрипции\" data-i18n-placeholder=\"adhkarUi.textPlaceholder\"></textarea></label><p role=\"alert\"></p><button class=\"button\" type=\"submit\" data-i18n=\"adhkarUi.addAndOpen\">Добавить и открыть</button></form></section>");
 const picker=document.getElementById('short-dhikr-picker');
 const choose=async(action,value)=>{const result=await freeStore.change(action,value,p.account);if(!active())return;if(!result.ok){toastUi(result.reason==='account_changed'?'Аккаунт изменился. Откройте счётчик снова.':'Не удалось сохранить выбор. Повторите.');return;}closeModal();freeCounter();};
 picker.querySelectorAll('[data-short-dhikr]').forEach(button=>button.onclick=()=>choose('select',button.dataset.shortDhikr));
 picker.querySelectorAll('[data-remove-short]').forEach(button=>button.onclick=()=>{if(window.confirm(adhkarMessage('Убрать этот зикр? Общее число повторений сохранится.')))void choose('remove-dhikr',button.dataset.removeShort);});
 const form=picker.querySelector('form'),add=picker.querySelector('#short-custom-open');add.onclick=()=>{form.hidden=!form.hidden;add.setAttribute('aria-expanded',String(!form.hidden));if(!form.hidden)form.querySelector('input').focus();};
 form.onsubmit=async event=>{event.preventDefault();if(!form.checkValidity()||!active())return;const button=form.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;const value={id:'custom-'+crypto.randomUUID().replaceAll('-',''),title:form.elements.title.value.trim(),text:form.elements.text.value.trim()};try{await choose('add-dhikr',value);}catch{uiSet(form.querySelector('[role=alert]'),'adhkarUi.dhikrSaveFailed',ADHKAR_UI_SOURCE.dhikrSaveFailed);}finally{if(form.isConnected)button.disabled=false;}};
}
function updateFreeCount(){
 const button=host?.querySelector('#free-tap');if(!button)return;const p=freeStore.snapshot();if(!p.ok)return;
 if(button.dataset.account!==p.account||button.dataset.dhikr!==(p.selected||DEFAULT_SHORT_DHIKR)){if(document.getElementById('short-dhikr-picker'))closeModal();freeCounter();return;}
 uiNumberSet(host.querySelector('#free-tap .count-number'),p.count);const caption=p.target?p.count>=p.target?'goalReached':'targetCaption':'noGoal';uiSet(host.querySelector('#free-tap .count-caption'),'adhkarUi.'+caption,ADHKAR_UI_SOURCE[caption],{count:p.target});uiNumberSet(host.querySelector('#free-total'),p.total);
 if(button.dataset.target!==String(p.target)){const select=host.querySelector('#counter-target'),custom=host.querySelector('#counter-custom');select.value=[0,33,100].includes(p.target)?String(p.target):'custom';custom.hidden=select.value!=='custom';custom.value=p.target||33;button.dataset.target=String(p.target);}
}

function icon(name){return '<img class="adhkar-icon" src="./assets/'+name+'.svg" alt="">'}
function theme(){document.body.classList.add('adhkar-signature','adhkar-hybrid')}
function hybridHub(fav){
 return "<section class=\"adhkar-hub\" aria-labelledby=\"adhkar-hub-title\"><div class=\"hybrid-heading\"><span class=\"eyebrow\" data-i18n=\"adhkarUi.dailyEyebrow\">ЕЖЕДНЕВНОЕ ПОМИНАНИЕ</span><h1 id=\"adhkar-hub-title\" data-i18n=\"nav.adhkar\">Азкары</h1><p data-i18n=\"adhkarUi.periodIntro\">Утро и вечер. В своём темпе.</p></div><div class=\"hybrid-library\"><button id=\"all-dhikr\" type=\"button\"><span data-i18n=\"adhkarUi.allAdhkar\">Все азкары</span> <span>"+uiNumberLeaf(data.items.length)+'</span></button><button id="favorite-dhikr" type="button">'+uiLeaf('adhkarUi.favoriteAdhkar','Избранные азкары')+' <span>'+uiNumberLeaf(fav.length)+'</span></button></div><div class="adhkar-hub-tiles"><div class="hybrid-collections">'+['morning','evening'].map(key=>{const g=data.groups[key],done=completed(progress(key),key);return'<button type="button" class="hybrid-collection '+key+(activePeriod===key?' is-current':'')+'" data-group="'+key+'"><span class="hybrid-emblem">'+icon(key==='morning'?'sun':'moon-stars')+'</span><span class="hybrid-collection-copy"><strong>'+adhkarGroupLeaf(key,g.name)+'</strong><span>'+uiLeaf('adhkarUi.adhkarCount','{count} азкаров',{count:g.ids.length})+(done?' · '+uiLeaf('adhkarUi.doneCount','{count} завершено',{count:done}):'')+'</span></span><span class="adhkar-period-badge" '+(activePeriod===key?'':'hidden')+"><span data-i18n=\"adhkarUi.now\">Сейчас</span></span>"+'<span class="hybrid-collection-progress"'+uiAttributeAttrs('aria-label','adhkarUi.completedCount',{done,total:g.ids.length})+'><span style="width:'+done/g.ids.length*100+'%"></span></span></button>';}).join('')+'</div><button type="button" class="hybrid-collection daily-dua-entry" id="saved-dua-open"><span class="hybrid-emblem">'+icon('star')+"</span><span class=\"hybrid-collection-copy\"><strong data-i18n=\"adhkarUi.favoriteDuas\">Избранные дуа</strong><span data-i18n=\"adhkarUi.savedForYou\">Сохранённое для вас</span></span>"+'</button><button type="button" class="hybrid-collection daily-dua-entry" id="daily-dua-open"><span class="hybrid-emblem">'+icon('book')+"</span><span class=\"hybrid-collection-copy\"><strong data-i18n=\"adhkarUi.dailyDuas\">Повседневные дуа</strong><span data-i18n=\"adhkarUi.situations\">Дом, еда, сон и другие ситуации</span></span>"+'</button><button type="button" class="hybrid-collection own-counter-entry" id="free-counter"><span class="hybrid-emblem">'+icon('list-ul')+"</span><span class=\"hybrid-collection-copy\"><strong data-i18n=\"adhkarUi.ownCounter\">Свой счётчик</strong><span data-i18n=\"adhkarUi.shortAndCustom\">Короткие зикры и ваши тексты</span></span>"+'</button></div></section>';
}

function hub(){feedback.stop();if(document.getElementById('short-dhikr-picker'))closeModal();document.body.classList.add('adhkar-hub-open');clearCounter();clearSwipe();group=null;eveningDay=null;rememberView();stopDhikrAudio();document.body.classList.remove('adhkar-reading');document.body.classList.remove('adhkar-focus');theme();const fav=read('adhkar-favorites',[]);paint(hybridHub(fav));host.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{group=b.dataset.group;selectAdhkar(group);list()});host.querySelector('#all-dhikr').onclick=()=>{group='all';data.groups.all={name:'Все зикры',ids:data.items.map(i=>i.id)};list()};host.querySelector('#favorite-dhikr').onclick=()=>{group='favorites';data.groups.favorites={name:'Избранное',ids:read('adhkar-favorites',[]).filter(id=>data.items.some(i=>i.id===id))};list()};host.querySelector('#saved-dua-open').onclick=()=>enterAdhkarView('#adhkar?view=duas&favorites=1');host.querySelector('#daily-dua-open').onclick=()=>{enterAdhkarView('#adhkar?view=duas')};host.querySelector('#free-counter').onclick=freeCounter;window.scrollTo(0,0)}
function list(){feedback.stop();if(document.getElementById('short-dhikr-picker'))closeModal();document.body.classList.remove('adhkar-hub-open');clearCounter();clearSwipe();rememberView('list');stopDhikrAudio();document.body.classList.remove('adhkar-reading');theme();document.body.classList.add('adhkar-focus');const g=data.groups[group],p=progress(group),favorites=read('adhkar-favorites',[]),totals=progressStore.totals();paint('<div class="dhikr-list-shell"><div class="dhikr-list-heading"><span>'+adhkarGroupLeaf(group,g.name)+'</span><span>'+uiLeaf('adhkarUi.cardCount','{count} карточек',{count:g.ids.length})+'</span></div><div class="dhikr-list">'+g.ids.map((id,index)=>{const item=adhkarPresentation(data.items.find(i=>i.id===id)),n=countFor(p,item),preview=displayedVerses(item).map(v=>v.transliteration).join(' ');return '<article style="--item-progress:'+n/item.target*100+'%" class="dhikr-list-card '+(n>=item.target?'finished':'')+'"><button class="dhikr-open" data-index="'+index+'"><span class="salah-list-number" aria-hidden="true">'+String(index+1).padStart(2,'0')+'</span><strong lang="ru" translate="no">'+esc(item.title)+'</strong><p lang="ru" translate="no">'+esc(preview)+'</p><span>'+uiNumberLeaf(n)+' / '+uiNumberLeaf(item.target)+' <span class="dhikr-list-total"'+uiAttributeAttrs('aria-label','adhkarUi.totalRepetitions',{count:totals[id]||0})+'>('+uiNumberLeaf(totals[id]||0)+')</span>'+(n>=item.target?' · '+uiLeaf('adhkarUi.completed','Выполнено'):'')+'</span></button><button class="dhikr-favorite" data-favorite="'+id+'"'+uiAttributeAttrs('aria-label',favorites.includes(id)?'adhkarUi.favoriteRemove':'adhkarUi.favoriteAdd')+' aria-pressed="'+favorites.includes(id)+'">'+icon(favorites.includes(id)?'star-fill':'star')+'</button></article>'}).join('')+'</div>'+(g.ids.length?'<button class="button dhikr-continue" id="dhikr-continue">'+uiLeaf(Object.values(p.counts).some(n=>n>0)?'adhkarUi.continueReading':'adhkarUi.startInOrder',Object.values(p.counts).some(n=>n>0)?'Продолжить чтение':'Начать по порядку')+'</button>':"<p class=\"muted\" data-i18n=\"adhkarUi.favoriteHint\">Нажмите звезду возле зикра, чтобы сохранить его здесь.</p>")+"<div class=\"dhikr-list-footer\"><button class=\"dhikr-circle\" id=\"dhikr-back\" aria-label=\"Назад\" data-i18n-aria-label=\"common.back\">"+icon('arrow-left')+"</button><button class=\"dhikr-circle\" id=\"dhikr-exit\" aria-label=\"Закрыть азкары\" data-i18n-aria-label=\"adhkarUi.exitLabel\">"+icon('x-lg')+'</button></div></div>');host.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{cursor=Number(b.dataset.index);card();window.scrollTo(0,0)});host.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favorite,fav=read('adhkar-favorites',[]);write('adhkar-favorites',fav.includes(id)?fav.filter(x=>x!==id):[...fav,id]);if(group==='favorites')data.groups.favorites.ids=read('adhkar-favorites',[]);list()});host.querySelector('#dhikr-continue')?.addEventListener('click',()=>{cursor=Math.min(p.cursor,g.ids.length-1);card();window.scrollTo(0,0)});host.querySelector('#dhikr-back').onclick=hub;host.querySelector('#dhikr-exit').onclick=()=>{stopAdhkar();hub()};window.scrollTo(0,0)}
function hadithInfo(item){const summaries={sayyid:'Шаддад ибн Аус передал слова Пророка о главной молитве прощения. В хадисе говорится о её произнесении днём и ночью с убеждённостью в её смысле.',asbahna:'Ибн Мас‘уд передал дуа Пророка при наступлении вечера и соответствующее дуа при наступлении утра.',amsayna:'Ибн Мас‘уд передал дуа Пророка при наступлении вечера и соответствующее дуа при наступлении утра.',tasbih:'Абу Хурайра передал наставление произносить эту формулу сто раз утром и вечером.',protection:'Усман ибн Аффан передал наставление произносить эту формулу три раза утром и вечером.',surah112:'Абдуллах ибн Хубайб передал наставление читать Аль-Ихлас, Аль-Фаляк и Ан-Нас по три раза утром и вечером.',surah113:'Абдуллах ибн Хубайб передал наставление читать Аль-Ихлас, Аль-Фаляк и Ан-Нас по три раза утром и вечером.',surah114:'Абдуллах ибн Хубайб передал наставление читать Аль-Ихлас, Аль-Фаляк и Ан-Нас по три раза утром и вечером.',afiya:'Ибн Умар передал, что Пророк не оставлял это дуа утром и вечером.',bika:'Абу Хурайра передал утреннее и вечернее дуа Пророка.',bikaEvening:'У Ибн Маджи 3868 приведён отдельный вечерний вариант этой молитвы.',alim:'Абу Бакр попросил научить его словам для утра и вечера. Передано дуа о защите от зла души и шайтана.',hayy:'Анас передал наставление Пророка Фатиме произносить это дуа утром и вечером.',tahlil:'В Сахих аль-Бухари 6404 приведено достоинство десяти повторений этой формулы без ограничения временем суток.',raditu:'У Ибн Маджи 3870 приведена эта формула для утра и вечера; число трёх повторений в указанной передаче не установлено.',hasbi:'У Абу Дауда 5081 приведён вариант с семью повторениями. Оценки передач этого сообщения различаются.'};uiModal('<div class="modal-head"><h2 lang="ru" translate="no">'+esc(item.title)+"</h2><button class=\"icon-button\" data-close aria-label=\"Закрыть\" data-i18n-aria-label=\"common.close\">"+icon('x-lg')+'</button></div><p class="hadith-summary" lang="ru" translate="no">'+esc(summaries[item.id]||'Текст и порядок повторений приведены в указанном источнике.')+"</p><p class=\"muted\" data-i18n=\"adhkarUi.summaryDisclaimer\">Краткое изложение содержания хадиса или примечания сборника; не дословный русский перевод.</p><p class=\"hadith-grade\" lang=\"ru\" translate=\"no\">"+esc(item.grade)+'</p>'+(item.sourceNote?'<p lang="ru" translate="no">'+esc(item.sourceNote)+'</p>':'')+"<p class=\"hadith-source\"><span data-i18n=\"adhkarUi.sourceLabel\">Источник:</span> <a href=\""+esc(item.source)+'" target="_blank" rel="noopener">'+esc(item.id==='sayyid'?'Сахих аль-Бухари':item.sourceLabel)+'</a></p>'+(item.additionalSource?'<p class="source-reference"><a href="'+esc(item.additionalSource)+"\" target=\"_blank\" rel=\"noopener\"><span data-i18n=\"adhkarUi.additionalSource\">Другой источник или вариант передачи</span></a></p>":''))}
function bindSwipe(){const shell=host.querySelector('.adhkar-shell');shell.tabIndex=0;shell.addEventListener('keydown',e=>{if(e.target.closest('button,a,input,select,textarea,summary,[contenteditable="true"]'))return;if(e.key==='ArrowLeft'){e.preventDefault();host.querySelector('#adhkar-next').click()}if(e.key==='ArrowRight'&&cursor>0){e.preventDefault();host.querySelector('#adhkar-prev').click()}});disposeSwipe=bindNativeCardSwipe(shell.querySelector('.dhikr-passage'),{gestureSurface:host,onBoundaryBack:()=>host.querySelector('#adhkar-close')?.click(),onSuppress:()=>{suppressTapUntil=Date.now()+500},preview:direction=>{const ids=data.groups[group].ids,index=cursor+(direction<0?1:-1);if(index<0)return null;const wrap=document.createElement('div');wrap.innerHTML=uiHtml(index>=ids.length?"<section class=\"lesson-passage\"><h2 class=\"dhikr-reading-title\" data-i18n=\"adhkarUi.finishReading\">Завершить чтение</h2><p class=\"lesson-translation\" data-i18n=\"adhkarUi.viewResult\">Посмотреть результат</p></section>":readingText(data.items.find(i=>i.id===ids[index])));return wrap.firstElementChild;},commit:(direction,incoming)=>{const ids=data.groups[group].ids;if(direction<0){if(cursor>=ids.length-1){summary()}else{cursor++;card(0,incoming)}}else if(cursor>0){cursor--;card(0,incoming)}window.scrollTo(0,0)}})}

window.addEventListener('storage',event=>{if(event.key!=='salah:adhkar-progress-v2'&&event.key!=='salah:dhikr-free'&&event.key!=='salah:counter-active-account')return;updateFreeCount();if(!group||!data)return;const button=host?.querySelector('#adhkar-count');if(!button)return;const item=data.items.find(i=>i.id===button.dataset.dhikrId);if(item)updateCount(item,progress(group))});

const dhikrAudioOwner='adhkar-card';
function stopDhikrAudio(){dhikrAudioToken++;const current=dhikrAudio;dhikrAudio=null;if(current){for(const name of ['onended','onerror','onpause','onplay','onplaying','ontimeupdate','onloadedmetadata','ondurationchange'])current[name]=null;current.pause();if(current.removeAttribute)current.removeAttribute('src');else current.src='';current.load?.();}setForegroundAudio(dhikrAudioOwner,false);}
function setDhikrAudioLabel(button,label,playing=false){button.innerHTML='<svg class="dhikr-audio-icon" viewBox="0 0 24 24" aria-hidden="true">'+(playing?'<path d="M8 5v14M16 5v14"/>':'<path d="M9 6 18 12 9 18Z"/>')+'</svg>';const key={Прослушать:'audioPlay',Пауза:'audioPause',Продолжить:'audioResume',Повторить:'audioRetry'}[label];uiAttribute(button,'aria-label','adhkarUi.'+key,label+' азкар');uiAttribute(button,'title','adhkarUi.'+key,label+' азкар');button.setAttribute('aria-pressed',String(playing));}

function pauseDhikrAudio(){const button=host?.querySelector('#dhikr-play');dhikrAudio?.pause();setForegroundAudio(dhikrAudioOwner,false);if(button)setDhikrAudioLabel(button,'Продолжить');}
registerPlayback(dhikrAudioOwner,pauseDhikrAudio);
function bindDhikrAudio(item){
 const button=host.querySelector('#dhikr-play'),recording=adhkarRecording(item);if(!button||!recording)return;
 const status=host.querySelector('#dhikr-audio-status');
 // Warm just this card, without playback, focus ownership or a library download.
 if(!dhikrAudio)try{dhikrAudio=new Audio(recording.url);preloadPronunciation(dhikrAudio);}catch{}
 button.onclick=event=>{
  // Replacing the SVG detaches the original click target before it bubbles.
  // Consume it here so a play/pause tap cannot also open the card explanation.
  event?.stopPropagation?.();
  if(dhikrAudio&&!dhikrAudio.paused){pauseDhikrAudio();return;}
  if(dhikrAudio?.error)stopDhikrAudio();
  if(!dhikrAudio){dhikrAudio=new Audio(recording.url);dhikrAudio.preload='none';}
  const current=dhikrAudio,version=dhikrAudioToken,valid=()=>current===dhikrAudio&&version===dhikrAudioToken;
  const failure=()=>{if(!valid())return;stopDhikrAudio();if(button.isConnected){button.removeAttribute('aria-busy');setDhikrAudioLabel(button,'Повторить');uiSet(status,'adhkarUi.audioFailed',ADHKAR_UI_SOURCE.audioFailed);}};
  current.onerror=failure;
  current.onplay=()=>{if(valid()&&!current.paused){setForegroundAudio(dhikrAudioOwner,true);setDhikrAudioLabel(button,'Пауза',true);}};
  current.onplaying=()=>{if(valid()&&!current.paused){button.removeAttribute('aria-busy');uiRaw(status,'');}};
  current.onpause=()=>{if(valid()&&current.paused){button.removeAttribute('aria-busy');setForegroundAudio(dhikrAudioOwner,false);setDhikrAudioLabel(button,'Продолжить');}};
  current.onended=()=>{if(!valid())return;stopDhikrAudio();if(button.isConnected){button.removeAttribute('aria-busy');setDhikrAudioLabel(button,'Прослушать');uiRaw(status,'');}};
  claimPlayback(dhikrAudioOwner);setForegroundAudio(dhikrAudioOwner,true);setDhikrAudioLabel(button,'Пауза',true);button.setAttribute('aria-busy','true');uiSet(status,'adhkarUi.audioLoading',ADHKAR_UI_SOURCE.audioLoading);
  try{Promise.resolve(current.play()).then(()=>{if(valid()){button.removeAttribute('aria-busy');uiRaw(status,'');}}).catch(error=>{if(valid()&&current.paused&&error?.name==='AbortError')return;failure();});}catch{failure();}
 };
}

function readingLayout(){const shell=host?.querySelector('.adhkar-shell');if(!shell)return;const selected=['adhkar-arabic','adhkar-translation','adhkar-translit'].filter(key=>host.querySelector('#'+key)?.checked).length;shell.classList.toggle('adhkar-single-text',selected===1);}

export function updateAdhkarPeriod(period,{resumeEvening=resumePreviousEvening}={}){
 activePeriod=period;resumePreviousEvening=resumeEvening;
 if(!host||!data)return;
 host.querySelectorAll('[data-group]').forEach(button=>{const current=button.dataset.group===period;button.classList.toggle('is-current',current);const badge=button.querySelector('.adhkar-period-badge');if(badge)badge.hidden=!current});
 const counter=host.querySelector('#adhkar-count');
 if(counter&&!counter.dataset.pending&&data.groups[group]){const item=data.items.find(item=>item.id===counter.dataset.dhikrId);if(item){const p=progress(group);updateCount(item,p);if(group==='evening'&&p._day!==dateKey()&&new URLSearchParams(location.hash.split('?')[1]||'').get('day')!==p._day)rememberView('card',item.id)}}
 if(group==='evening'&&host.querySelector('.dhikr-list-shell')){const p=progress(group);if(p._day!==dateKey()&&new URLSearchParams(location.hash.split('?')[1]||'').get('day')!==p._day)list()}
}

window.addEventListener('salah:counter-restored',()=>{updateFreeCount();if(!document.body.classList.contains('adhkar-signature')||!group||!data)return;const button=host?.querySelector('#adhkar-count');if(button){const item=data.items.find(i=>i.id===button.dataset.dhikrId);if(item)updateCount(item,progress(group));}else if(host?.querySelector('.dhikr-list'))list();});
